package com.careerverse.servlet;
import com.careerverse.model.CareerData; import com.careerverse.service.CareerEngine; import com.google.gson.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.util.*;
@WebServlet("/app/api/careers") public class CareerServlet extends HttpServlet{private final Gson g=new Gson();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{List<Map<String,Object>>out=new ArrayList<>();for(var c:CareerData.ALL){Map<String,Object>m=new LinkedHashMap<>();m.put("id",c.id());m.put("name",c.name());m.put("icon",c.icon());m.put("description",c.description());m.put("languages",c.languages());m.put("skills",c.skills());m.put("projects",c.projects());out.add(m);}s.setContentType("application/json");s.getWriter().print(g.toJson(out));}}
